            d = np.hypot(dx, dy)
            rr = z[3 * i + 2] + z[3 * j + 2]
            if d - rr < 5e-3:
                active.append((i, j, d - rr))
        if active:
            k = rng.randint(2, min(7, len(active) + 1))
            chosen = rng.choice(len(active), size=k, replace=False)
            for idx in chosen:
                i, j, _ = active[idx]
                dx = z[3 * i] - z[3 * j]
                dy = z[3 * i + 1] - z[3 * j + 1]
                d = np.hypot(dx, dy)
                if d < 1e-12:
                    ang = rng.rand() * 2 * np.pi
                    ux, uy = np.cos(ang), np.sin(ang)
                else:
                    ux, uy = dx / d, dy / d
                step = scale * (0.5 + rng.rand())
                z[3 * i] += ux * step
                z[3 * i + 1] += uy * step
                z[3 * j] -= ux * step
                z[3 * j + 1] -= uy * step
        n_jit = rng.randint(0, 4)
        if n_jit > 0:
            idxs = rng.choice(n, size=n_jit, replace=False)
            for i in idxs:
                z[3 * i] += rng.randn() * scale
                z[3 * i + 1] += rng.randn() * scale
                z[3 * i + 2] = max(1e-3, z[3 * i + 2] + rng.randn() * scale * 0.3)
        if rng.rand() < 0.3:
            radii = z[2::3].copy()
            perm = rng.permutation(n)
            z[2::3] = radii[perm]
        return repair(z)

    attempts = 0
    scale = 0.02
    while time.process_time() < deadline:
        attempts += 1
        z0 = perturb(best, scale)
        z = run_slsqp(z0, maxiter=300)
        if z is not None and is_feasible(z) and score(z) > best_val + 1e-10:
            best = z.copy()
            best_val = score(z)
        if attempts % 20 == 0:
            scale = max(0.003, scale * 0.9)

    out = best.reshape(n, 3).copy()
    out[:, 2] = np.maximum(out[:, 2] - 1e-8, 1e-9)

    def enforce(out):
        for _ in range(80):
            changed = False
            for i in range(n):
                x, y, r = out[i]
                m = min(x, 1 - x, y, 1 - y)
                if r > m:
                    out[i, 2] = max(m - 1e-12, 1e-12)
                    changed = True
            for i in range(n):
                for j in range(i + 1, n):
                    dx = out[i, 0] - out[j, 0]
                    dy = out[i, 1] - out[j, 1]
                    d = np.hypot(dx, dy)
                    rs = out[i, 2] + out[j, 2]
                    if d < rs:
                        excess = rs - d
                        out[i, 2] -= excess / 2 + 1e-13
                        out[j, 2] -= excess / 2 + 1e-13
                        changed = True
            if not changed:
                break
        out[:, 2] = np.maximum(out[:, 2], 1e-9)

    enforce(out)
    return out
